"""Randomised differential test: submission/main.py vs the reference."""
import json
import random
import subprocess
import sys
import itertools
from fractions import Fraction

sys.path.insert(0, '/workspace/tmp')
import reference

MAIN = '/workspace/submission/main.py'
TYPES = ('c2p', 'p2p', 'p2c')


def find_order(core, scopes):
    """Greedy elimination order over the scope graph with width <= 4."""
    if not core:
        return []
    index = {link: i for i, link in enumerate(core)}
    adj = {i: set() for i in range(len(core))}
    for scope in scopes.values():
        for a in scope:
            for b in scope:
                if a != b:
                    adj[a].add(b)
    remaining = set(adj)
    order = []
    width = 0
    while remaining:
        best = None
        for node in sorted(remaining):
            nbrs = adj[node]
            fill = 0
            for a in nbrs:
                for b in nbrs:
                    if a != b and b not in adj[a]:
                        fill += 1
            score = (fill, len(nbrs))
            if best is None or score < best[0]:
                best = (score, node)
        node = best[1]
        nbrs = list(adj[node])
        width = max(width, len(nbrs))
        for a in nbrs:
            for b in nbrs:
                if a != b:
                    adj[a].add(b)
                    adj[b].add(a)
        for a in nbrs:
            adj[a].discard(node)
        del adj[node]
        remaining.discard(node)
        order.append(core[node])
    if width > 4:
        return None
    return order


def scopes_for(doc):
    ixps = set(doc['ixps'])
    agg = reference.aggregate(doc['rib'], ixps)
    core_paths, _ = reference.peel(agg)
    core = set()
    for p in core_paths:
        core |= reference.links_of(p)
    core = sorted(core)
    index = {l: i for i, l in enumerate(core)}
    occ = {i: [] for i in range(len(core))}
    for p, c in core_paths.items():
        for i in range(len(p)-1):
            e = (min(p[i], p[i+1]), max(p[i], p[i+1]))
            L, R = reference.context_types(p, i, e)
            occ[index[e]].append((c, L, R))
    scopes = {}
    for e, items in occ.items():
        s = {e}
        for _c, L, R in items:
            for spec in (L, R):
                if spec[0] == 'var':
                    s.add(index[spec[1]])
        scopes[e] = sorted(s)
    return core, scopes


def random_doc(rng):
    nasn = rng.randint(3, 7)
    asns = rng.sample(range(1, 60), nasn)
    ixps = []
    if rng.random() < 0.3:
        ixps = [rng.choice(asns)]
    rib = []
    for _ in range(rng.randint(1, 8)):
        length = rng.randint(0, 5)
        path = [rng.choice(asns) for _ in range(length)]
        rib.append({'path': path, 'count': rng.randint(1, 5)})
    priors = []
    for _ in range(rng.randint(0, 3)):
        u, v = rng.sample(asns, 2)
        priors.append({'link': [u, v],
                       'weights': [rng.randint(0, 4) for _ in range(3)]})
    priors = [p for p in priors if sum(p['weights']) > 0]
    seen = set()
    keep = []
    for p in priors:
        k = tuple(sorted(p['link']))
        if k in seen:
            continue
        seen.add(k)
        keep.append(p)
    priors = keep
    declared = []
    for _ in range(rng.randint(0, 2)):
        u, v = rng.sample(asns, 2)
        declared.append({'link': [u, v], 'rel': rng.choice(TYPES)})
    seen = set()
    keep = []
    for p in declared:
        k = tuple(sorted(p['link']))
        if k in seen:
            continue
        seen.add(k)
        keep.append(p)
    declared = keep
    queries = []
    for i in range(rng.randint(0, 4)):
        length = rng.randint(0, 5)
        path = [rng.choice(asns) for _ in range(length)]
        queries.append({'id': 'q%d' % i, 'path': path,
                        'threshold': [rng.randint(0, 3), rng.randint(1, 3)]})
    return {'version': 1, 'ixps': ixps, 'rib': rib, 'priors': priors,
            'declared': declared, 'order': [], 'queries': queries}


def close(a, b, tol=1e-9):
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(close(a[k], b[k], tol) for k in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(close(x, y, tol) for x, y in zip(a, b))
    if isinstance(a, bool) or isinstance(b, bool):
        return a is b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        if a is None or b is None:
            return a == b
        return abs(a - b) <= tol
    return a == b


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    skipped = 0
    zero = 0
    for n in range(count):
        doc = random_doc(rng)
        core, scopes = scopes_for(doc)
        order = find_order(core, scopes)
        if order is None:
            skipped += 1
            continue
        doc['order'] = [list(l) for l in order]
        expected = reference.run(doc)
        if expected.get('error') == 'zero-partition':
            zero += 1
        raw = json.dumps(doc).encode()
        proc = subprocess.run([sys.executable, '-I', MAIN], input=raw,
                              stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if proc.returncode != 0:
            print('FAIL(exit) case', n, proc.stderr.decode()[:500])
            print(json.dumps(doc))
            return 1
        try:
            actual = json.loads(proc.stdout)
        except Exception as exc:
            print('FAIL(json) case', n, exc, proc.stdout[:300])
            print(json.dumps(doc))
            return 1
        if not close(expected, actual):
            print('FAIL(mismatch) case', n)
            print('input ', json.dumps(doc))
            print('expect', json.dumps(expected))
            print('actual', json.dumps(actual))
            return 1
    print('ok: %d cases (%d skipped for width, %d zero-partition)' %
          (count - skipped, skipped, zero))
    return 0


if __name__ == '__main__':
    sys.exit(main())
